import { getVercelOidcToken } from '@vercel/oidc';
import { isDetachedInteractiveAuth, validateCallbackUrl, validateWebhookUrl, } from './internal/url-validation.js';
import { createConnectErrorFromResponse } from './token.js';
import { resolveBaseUrl } from './internal/base-url.js';
/**
 * Create an operator installation request for an app-scoped connector.
 *
 * @experimental This API is feature-gated while experimental. Contact Vercel
 * to enable access before using it.
 */
export async function experimental_startInstallation(connector, params = {}, options) {
    if (!connector) {
        throw new Error('connector is required');
    }
    const detachedInteractiveAuth = isDetachedInteractiveAuth();
    if (!detachedInteractiveAuth && options?.returnUrl !== undefined) {
        validateCallbackUrl(options.returnUrl, 'returnUrl');
    }
    if (options?.webhook !== undefined) {
        validateWebhookUrl(options.webhook);
    }
    const vercelToken = options?.vercelToken ?? (await getVercelOidcToken());
    const baseUrl = resolveBaseUrl(options);
    const endpoint = `${baseUrl}/v1/connect/install/${encodeURIComponent(connector)}`;
    const deviceCode = options?.deviceCode ?? (detachedInteractiveAuth ? true : undefined);
    const returnUrl = !detachedInteractiveAuth && options?.returnUrl !== undefined
        ? { returnUrl: options.returnUrl }
        : {};
    const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            Authorization: `Bearer ${vercelToken}`,
        },
        body: JSON.stringify({
            ...params,
            ...returnUrl,
            ...(options?.webhook !== undefined && { webhook: options.webhook }),
            ...(options?.tenantId !== undefined && { tenantId: options.tenantId }),
            ...(deviceCode !== undefined && { deviceCode }),
            ...(options?.expiresInMs !== undefined && {
                expiresInMs: options.expiresInMs,
            }),
        }),
    });
    if (!response.ok) {
        throw await createConnectErrorFromResponse(response, 'Failed to start installation');
    }
    const data = await response.json();
    return data;
}
